import os
import subprocess
import tempfile
from flask import Flask, request, jsonify

app = Flask(__name__)

UPLOAD_DIR = os.environ.get('UPLOAD_DIR', '/tmp/uploads')
ALLOWED_EXTENSIONS = {'.pdf', '.docx', '.xlsx', '.pptx'}
MAX_FILE_SIZE = 10 * 1024 * 1024  # 10MB

def validate_filename(filename):
    """Basic filename validation - strips path traversal attempts"""
    basename = os.path.basename(filename)
    if not basename or basename.startswith('.'):
        return None
    return basename

def convert_document(input_path, output_format='pdf'):
    """Convert document using LibreOffice headless mode"""
    output_dir = tempfile.mkdtemp(prefix='conv_')
    cmd = f'libreoffice --headless --convert-to {output_format} --outdir {output_dir} {input_path}'
    result = subprocess.run(
        cmd,
        shell=True,
        capture_output=True,
        timeout=30
    )
    if result.returncode != 0:
        raise RuntimeError(f'Conversion failed: {result.stderr.decode()}')
    return output_dir

def extract_metadata(filepath):
    """Extract document metadata using exiftool"""
    tag_args = request.args.get('tags', '-Title -Author -CreateDate')
    cmd = f'exiftool {tag_args} {filepath}'
    result = subprocess.run(
        cmd,
        shell=True,
        capture_output=True,
        timeout=10
    )
    return result.stdout.decode()

@app.route('/api/v2/documents/upload', methods=['POST'])
def upload_document():
    if 'file' not in request.files:
        return jsonify({'error': 'No file provided'}), 400

    file = request.files['file']
    filename = validate_filename(file.filename)
    if not filename:
        return jsonify({'error': 'Invalid filename'}), 400

    ext = os.path.splitext(filename)[1].lower()
    if ext not in ALLOWED_EXTENSIONS:
        return jsonify({'error': f'Extension {ext} not allowed'}), 400

    file_content = file.read()
    if len(file_content) > MAX_FILE_SIZE:
        return jsonify({'error': 'File too large'}), 413

    os.makedirs(UPLOAD_DIR, exist_ok=True)
    filepath = os.path.join(UPLOAD_DIR, filename)
    with open(filepath, 'wb') as f:
        f.write(file_content)

    return jsonify({'status': 'uploaded', 'path': filepath}), 201

@app.route('/api/v2/documents/metadata', methods=['GET'])
def get_metadata():
    filename = request.args.get('filename')
    if not filename:
        return jsonify({'error': 'filename required'}), 400

    safe_name = validate_filename(filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    filepath = os.path.join(UPLOAD_DIR, safe_name)
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    metadata = extract_metadata(filepath)
    return jsonify({'metadata': metadata})

@app.route('/api/v2/documents/convert', methods=['POST'])
def convert_doc():
    data = request.get_json()
    filename = data.get('filename')
    output_format = data.get('format', 'pdf')

    safe_name = validate_filename(filename)
    if not safe_name:
        return jsonify({'error': 'Invalid filename'}), 400

    filepath = os.path.join(UPLOAD_DIR, safe_name)
    if not os.path.exists(filepath):
        return jsonify({'error': 'File not found'}), 404

    try:
        output_dir = convert_document(filepath, output_format)
        return jsonify({'status': 'converted', 'output_dir': output_dir})
    except Exception as e:
        return jsonify({'error': str(e)}), 500

@app.route('/health', methods=['GET'])
def health():
    return jsonify({'status': 'ok'})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=8080)
